# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">PEYGAMBERİMİZİN TORUNLARI: HZ. HASAN, HZ. HÜSEYİN VE HZ. ÜMÂME</text>\n  <rect x="20" y="48" width="320" height="190" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Hz. Hasan ve Hz. Hüseyin (r.a.)</text>\n  <text x="180" y="98" text-anchor="middle" font-size="11.5" fill="#14532d">• Hz. Fatıma ve Hz. Ali\'nin evlatlarıdır.</text>\n  <text x="180" y="122" text-anchor="middle" font-size="11.5" fill="#14532d">• Peygamberimiz onları «Dünyadaki iki</text>\n  <text x="180" y="142" text-anchor="middle" font-size="11.5" fill="#14532d">reyhanım (hoş kokulu çiçeğim)» diye severdi.</text>\n  <text x="180" y="168" text-anchor="middle" font-size="11.5" fill="#14532d">• Namazda secdeye vardığında sırtına</text>\n  <text x="180" y="188" text-anchor="middle" font-size="11.5" fill="#14532d">çıktıklarında inene kadar secdeyi uzatırdı.</text>\n  <text x="180" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">«Allah\'ım! Ben onları seviyorum, Sen de sev!»</text>\n\n  <rect x="360" y="48" width="320" height="190" rx="8" fill="#fdf2f8" stroke="#db2777" stroke-width="1.5"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">Hz. Ümâme ve Kız Çocuklarına Değer</text>\n  <text x="520" y="98" text-anchor="middle" font-size="11.5" fill="#831843">• Kızı Hz. Zeynep\'in kızı (torunu) Hz. Ümâme\'yi</text>\n  <text x="520" y="120" text-anchor="middle" font-size="11.5" fill="#831843">omzunda taşıyarak mescide gelirdi.</text>\n  <text x="520" y="146" text-anchor="middle" font-size="11.5" fill="#831843">• Rükû ve secdeye giderken yere bırakır,</text>\n  <text x="520" y="166" text-anchor="middle" font-size="11.5" fill="#831843">ayağa kalkarken tekrar omzuna alırdı.</text>\n  <text x="520" y="192" text-anchor="middle" font-size="11.5" fill="#831843">• Kız ve erkek çocukları arasında</text>\n  <text x="520" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#be185d">ayrım yapmadan eşit şefkat gösterirdi.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">HZ. ENES BİN MÂLİK VE ASRISAADET ÇOCUKLARIYLA İLETİŞİM (PH.5.2.1)</text>\n  <rect x="20" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#2563eb" stroke-width="1.5"/>\n  <text x="125" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Hz. Enes bin Mâlik (r.a.)</text>\n  <text x="125" y="98" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• Hicretten sonra 10 yaşındayken</text>\n  <text x="125" y="118" text-anchor="middle" font-size="11.5" fill="#1e3a8a">Peygamberimizin yanına verildi.</text>\n  <text x="125" y="144" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• 10 yıl boyunca O\'nun yanında</text>\n  <text x="125" y="164" text-anchor="middle" font-size="11.5" fill="#1e3a8a">büyüdü ve ilim öğrendi.</text>\n  <text x="125" y="190" text-anchor="middle" font-size="11.5" fill="#1e3a8a">• «Bana bir kez bile öf demedi,</text>\n  <text x="125" y="216" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">neden yaptın diye azarlamadı.»</text>\n\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="1.5"/>\n  <text x="350" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#b45309">Ebû Umeyr ve Üzüntüsü</text>\n  <text x="350" y="98" text-anchor="middle" font-size="11.5" fill="#78350f">• Hz. Enes\'in küçük kardeşi</text>\n  <text x="350" y="118" text-anchor="middle" font-size="11.5" fill="#78350f">Ebû Umeyr\'in «Nuğayr» adlı</text>\n  <text x="350" y="138" text-anchor="middle" font-size="11.5" fill="#78350f">serçe kuşu öldüğünde çok üzüldü.</text>\n  <text x="350" y="164" text-anchor="middle" font-size="11.5" fill="#78350f">• Peygamberimiz onu ziyaret edip</text>\n  <text x="350" y="184" text-anchor="middle" font-size="11.5" fill="#78350f">«Ey Ebû Umeyr! Nuğayr ne oldu?»</text>\n  <text x="350" y="216" text-anchor="middle" font-size="11" font-weight="bold" fill="#b45309">diyerek gönlünü aldı ve teselli etti.</text>\n\n  <rect x="470" y="48" width="210" height="190" rx="8" fill="#ecfeff" stroke="#0891b2" stroke-width="1.5"/>\n  <text x="575" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">Râfi bin Amr (Tatlı Öğüt)</text>\n  <text x="575" y="98" text-anchor="middle" font-size="11.5" fill="#155e75">• Aç olduğu için hurma ağaçlarını</text>\n  <text x="575" y="118" text-anchor="middle" font-size="11.5" fill="#155e75">taşlayan küçük Râfi\'yi azarlamadı.</text>\n  <text x="575" y="144" text-anchor="middle" font-size="11.5" fill="#155e75">• «Yavrum, ağacı taşlama; yere</text>\n  <text x="575" y="164" text-anchor="middle" font-size="11.5" fill="#155e75">düşenlerden ye» buyurdu.</text>\n  <text x="575" y="190" text-anchor="middle" font-size="11.5" fill="#155e75">• Başını okşayıp «Allah\'ım, karnını</text>\n  <text x="575" y="216" text-anchor="middle" font-size="11" font-weight="bold" fill="#0e7490">doyur» diye hayır duada bulundu.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ÇOCUKLARIN DÜNYASINDA PEYGAMBER SEVGİSİ (PH.5.2.2)</text>\n  <rect x="25" y="48" width="650" height="190" rx="8" fill="#f5f3ff" stroke="#7c3aed" stroke-width="1.5"/>\n  <text x="350" y="74" text-anchor="middle" font-size="13" font-weight="bold" fill="#5b21b6">Asrısaadet Çocuklarının Hz. Peygamber\'e (s.a.v.) Duyduğu Derin Sevgi</text>\n  <text x="55" y="104" font-size="12" fill="#4c1d95">• Seferden Dönüşte Karşılama: Peygamberimiz yolculuktan dönerken Medineli çocuklar</text>\n  <text x="70" y="124" font-size="12" fill="#1e293b">şehir dışına kadar koşarak O\'nu neşeyle karşılar, O da çocukları bineğine bindirirdi.</text>\n  <text x="55" y="152" font-size="12" fill="#4c1d95">• Sözünü Dinleme ve Örnek Alma: Çocuklar Peygamberimizin öğütlerini (sofra adabı,</text>\n  <text x="70" y="172" font-size="12" fill="#1e293b">selamlaşma, dürüstlük, namaz) büyük bir istekle uygular ve birbirlerine anlatırlardı.</text>\n  <text x="55" y="200" font-size="12" fill="#4c1d95">• İlim ve Cesaretle Bağlanma: Küçük sahabiler (Hz. Ali, Zeyd bin Sâbit, Abdullah bin</text>\n  <text x="70" y="220" font-size="12" fill="#1e293b">Abbas, Üsâme bin Zeyd) O\'nun meclisinde bulunmak ve Kur\'an öğrenmek için yarışırlardı.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
